"""Replace tool/Field description strings from a JSON edit list."""
import ast, json, sys, textwrap

def offsets(src):
    lines = src.splitlines(keepends=True)
    starts, pos = [], 0
    for line in lines:
        starts.append(pos); pos += len(line)
    starts.append(pos)
    return starts

def literal(text, indent, first_width):
    # wrap into implicit-concatenated double-quoted strings
    words = text.split(' ')
    segs, cur, width = [], '', first_width
    for w in words:
        cand = (cur + ' ' + w) if cur else w
        if len(cand) + 3 > width and cur:
            segs.append(cur + ' ')
            cur = w
            width = 88 - len(indent)
        else:
            cur = cand
    segs.append(cur)
    def q(s):
        return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
    out = q(segs[0])
    for s in segs[1:]:
        out += '\n' + indent + q(s)
    return out

def main(edits_path):
    edits = json.load(open(edits_path, encoding='utf-8'))
    by_file = {}
    for e in edits:
        by_file.setdefault(e['file'], []).append(e)
    for path, items in by_file.items():
        src = open(path, encoding='utf-8').read()
        starts = offsets(src)
        tree = ast.parse(src)
        targets = []  # (start, end, kw_col, new_text)
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            fname = getattr(node.func, 'attr', None) or getattr(node.func, 'id', None)
            if fname not in ('tool', 'Field'):
                continue
            title = next((k.value.value for k in node.keywords
                          if k.arg == 'title' and isinstance(k.value, ast.Constant)), None)
            for kw in node.keywords:
                if kw.arg != 'description' or not isinstance(kw.value, ast.Constant):
                    continue
                match = None
                for e in items:
                    if e['kind'] == 'tool' and fname == 'tool' and e['key'] == title:
                        match = e
                    elif e['kind'] == 'field' and fname == 'Field' and e['key'] == kw.value.lineno:
                        match = e
                if match is None:
                    continue
                v = kw.value
                s = starts[v.lineno - 1] + v.col_offset
                en = starts[v.end_lineno - 1] + v.end_col_offset
                targets.append((s, en, kw.col_offset, match['text'], match))
        seen = {id(t[4]) for t in targets}
        missing = [e for e in items if id(e) not in seen]
        if missing:
            raise SystemExit(f'no match in {path}: {[ (m["kind"], m["key"]) for m in missing ]}')
        for s, en, col, text, _ in sorted(targets, reverse=True):
            indent = ' ' * col
            first_width = 88 - col - len('description=')
            src = src[:s] + literal(text, indent, first_width) + src[en:]
        open(path, 'w', encoding='utf-8').write(src)
        print(f'{path}: {len(targets)} descriptions replaced')

main(sys.argv[1])
